    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            String block = "# settings\n"
                    + "name = Ada\n"
                    + "\n"
                    + "   port=8080\n"
                    + "name = Grace\n"
                    + "broken line\n"
                    + "empty=\n"
                    + "  # indented comment\n"
                    + "url = http://x/y?a=b\n";
            java.util.Map<String, String> config = ConfigBlockParser.parse(block);
            check("last duplicate key wins", "Grace", config.get("name"));
            check("leading spaces trimmed", "8080", config.get("port"));
            check("empty value allowed", "", config.get("empty"));
            check("split at the FIRST equals only", "http://x/y?a=b", config.get("url"));
            check("comments and junk skipped", null, config.get("broken line"));
            check("entry count", 4, config.size());
            check("getInt on a number", 8080, ConfigBlockParser.getInt(config, "port", 0));
            check("getInt on a non-number", -1, ConfigBlockParser.getInt(config, "name", -1));
            check("getInt on a missing key", 7, ConfigBlockParser.getInt(config, "timeout", 7));
            check("empty block", 0, ConfigBlockParser.parse("").size());
        } catch (Throwable t) {
            broke("parse", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
