import java.util.LinkedHashMap;
import java.util.Map;

public class ConfigBlockParser {

    public static Map<String, String> parse(String block) {
        Map<String, String> config = new LinkedHashMap<>();
        for (String raw : block.split("\\n", -1)) {
            String line = raw.trim();
            if (line.isEmpty() || line.startsWith("#")) {
                continue;
            }
            int equals = line.indexOf('=');
            if (equals < 0) {
                continue;
            }
            String key = line.substring(0, equals).trim();
            String value = line.substring(equals + 1).trim();
            config.put(key, value);
        }
        return config;
    }

    public static int getInt(Map<String, String> config, String key, int fallback) {
        String value = config.get(key);
        if (value == null) {
            return fallback;
        }
        try {
            return Integer.parseInt(value);
        } catch (NumberFormatException wrongFormat) {
            return fallback;
        }
    }
}
